});

async function updateProfessionalData() {
  try {
    // Get first specialty (Cardiología)
    const specialtyResult = await pool.query(''SELECT id FROM specialties WHERE name ILIKE \''%cardio%\'' LIMIT 1'');
    const specialtyId = specialtyResult.rows[0]?.id;

    // Get the first professional
    const profResult = await pool.query(''SELECT id FROM professionals LIMIT 1'');
    const professionalId = profResult.rows[0]?.id;

    if (professionalId && specialtyId) {
      // Update professional with sample data
      await pool.query(\`
        UPDATE professionals 
        SET 
          specialty_id = $1,
          consultation_fee = 75.00,
          city = ''Madrid'',
          address = ''Calle Gran Vía, 25, 28013 Madrid'',
          latitude = 40.4200,
          longitude = -3.7025,
          rating = 4.8,
          total_reviews = 132,
          office_hours = ''{"monday": {"start": "09:00", "end": "18:00"}, "tuesday": {"start": "09:00", "end": "18:00"}, "wednesday": {"start": "09:00", "end": "18:00"}, "thursday": {"start": "09:00", "end": "18:00"}, "friday": {"start": "09:00", "end": "18:00"}}'',
          services = ''{""Consulta cardiológica"", ""ECG"", ""Ecocardiograma"", ""Prueba de esfuerzo"", ""Holter""}'',
          about = ''Cardióloga especializada en arritmias con más de 10 años de experiencia. Comprometida con brindar atención médica de calidad y personalizada.'',
          education = ''Licenciatura en Medicina - Universidad Complutense de Madrid. Especialidad en Cardiología - Hospital Universitario La Paz. Máster en Arritmias - Universidad Europea de Madrid.'',
          experience_years = 12,
          languages = ''{""Español"", ""Inglés"", ""Francés""}'',
          verified = true,
          profile_completed = true,
          updated_at = NOW()
        WHERE id = $2
      \`, [specialtyId, professionalId]);

      console.log(''Professional data updated successfully'');

      // Update the user''s phone
      const userResult = await pool.query(''SELECT user_id FROM professionals WHERE id = $1'', [professionalId]);
      const userId = userResult.rows[0]?.user_id;

      if (userId) {
        await pool.query(''UPDATE users SET phone = $1 WHERE id = $2'', [''+34 91 123 45 67'', userId]);
        console.log(''User phone updated'');
      }
    }

    await pool.end();
  } catch (error) {
    console.error(''Error:'', error.message);
  }
}

updateProfessionalData();
")

